CREATE TABLE IF NOT EXISTS public.survey_crosstabs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_id uuid NOT NULL REFERENCES public.survey_questions(id) ON DELETE CASCADE,
  filter_type text NOT NULL,
  filter_label text NOT NULL,
  basis text NOT NULL DEFAULT 'segmento',
  segment_label text NOT NULL,
  segment_order int NOT NULL DEFAULT 0,
  candidate_name text NOT NULL,
  percentage numeric(5,2) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_survey_crosstabs_question ON public.survey_crosstabs(question_id);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.survey_crosstabs TO authenticated;
GRANT ALL ON public.survey_crosstabs TO service_role;
ALTER TABLE public.survey_crosstabs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "authenticated read survey_crosstabs" ON public.survey_crosstabs;
CREATE POLICY "authenticated read survey_crosstabs" ON public.survey_crosstabs FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "admins manage survey_crosstabs" ON public.survey_crosstabs;
CREATE POLICY "admins manage survey_crosstabs" ON public.survey_crosstabs FOR ALL TO authenticated
  USING (has_role(auth.uid(),'admin_master'::app_role) OR has_role(auth.uid(),'admin'::app_role))
  WITH CHECK (has_role(auth.uid(),'admin_master'::app_role) OR has_role(auth.uid(),'admin'::app_role));

DELETE FROM public.survey_crosstabs;

